    %scale_bcast = "mhlo.broadcast_in_dim"(%arg0) {
      broadcast_dimensions = dense<[0]>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %scaled = "mhlo.mul"(%gemm_out, %scale_bcast) : tensor<6x7xf32>

    // Step 3: Batch normalization
    // Compute mean and variance over batch dimension (dim 0)
    // mean: reduce over dim 0
    %dim0 = "mhlo.constant"() {value = dense<0>} : () -> index
    %reduction_dims = "mhlo.constant"() {value = dense<[0]>} : () -> tensor<1> of index
    // Compute mean
    %sum = "mhlo.reduce"(%scaled, %c0 = "mhlo.constant"() {value = dense<0.0>}) {
      dimensions = %reduction_dims,
      to_apply = "mhlo.add"
    } : (tensor<6x7xf32>, tensor<0.0>) -> tensor<7xf32>
    // sum shape: [7], divide by 6 to get mean
    %count = "mhlo.constant"() {value = dense<6>} : () -> tensor<1xi32>
    %count_f32 = "mhlo.convert"(%count) : tensor<1xi32> to tensor<1xf32>
    %mean = "mhlo.div"(%sum, %count_f32) : tensor<7xf32>

