    %mean_bcast = "mhlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0]>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    // difference = scaled - mean_bcast
    %diff = "mhlo.sub"(%scaled, %mean_bcast) : tensor<6x7xf32>
    // square difference
    %diff_sq = "mhlo.mul"(%diff, %diff) : tensor<6x7xf32>
