    // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
    %sqrt2 = "stablehlo.constant"() {value = dense<1.41421356237> : tensor<f32>} : () -> tensor<f32>
    %x_div_sqrt2 = "stablehlo.divide"(%shifted, %sqrt2) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %one_plus_erf = "stablehlo.add"(%erf_x, %one) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %gelu_factor = "stablehlo.multiply"(%shifted, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %gelu = "stablehlo.multiply"(%gelu_factor, %half) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // define half constant
    %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>

    // Step 4: ReLU activation
    // ReLU: max(0, x)
    %zero_f = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %relu = "stablehlo.maximum"(%gelu, %zero_f) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the result
    "stablehlo.return"(%relu) : (tensor<6x7xf32>) -> ()
  }
}

func.func @main(%x: tensor<2x4x3xf32>) -> tensor<3x2x4xf32> {
  %dim0 = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>
