  %dim2 = "stablehlo.constant"() {value = dense<2> : tensor<i64>} : () -> tensor<i64>

  // Transpose to swap axes 0 and 2: permutation = [2, 1, 0]
  %transposed = "stablehlo.transpose"(%x) {permutation = array<i64: 2, 1, 0>} : (tensor<2x4x3xf32>) -> tensor<3x4x2>

