// StableHLO program implementing the described model's forward pass
module {
  func.func @main(%arg0: tensor<7x7xf32>,        // gemm.weight
                   %arg1: tensor<7xf32>,          // gemm.bias
                   %arg2: tensor<7xf32>,          // batch_norm.weight
                   %arg3: tensor<7xf32>,          // batch_norm.bias
                   %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
    // Step 1: GEMM (linear layer)
    // gemm: input (6x7), weight (7x7) -> (6x7)
    %gemm_result = "stablehlo.dot_general"(%arg4, %arg0) {
      dot_dimension_numbers = {
        lhs_contracting_dimensions = dense<[1]> : tensor<1x1xi64>,
        rhs_contracting_dimensions = dense<[0]> : tensor<1x1xi64>,
        lhs_batch_dimensions = dense<[]> : tensor<0xi64>,
        rhs_batch_dimensions = dense<[]> : tensor<0xi64>
      },
      precision_config = {use_default_precision = true}
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

    // Add bias: broadcast bias to (6x7) and add
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_bias_added = "stablehlo.add"(%gemm_result, %bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 2: BatchNorm1d
    // batch_norm parameters: weight and bias (both shape 7)
    // Input shape: (6,7)
    // Compute mean and variance over batch (dim 0)
    %dim0 = "stablehlo.constant"() {value = dense<[0]> : tensor<1xi64>} : () -> tensor<1xi64>
    %mean = "stablehlo.reduce"(%gemm_bias_added, %dim0, "stablehlo.add") : (tensor<6x7xf32>, tensor<1xi64>) -> tensor<7xf32>
    %mean_divisor = "stablehlo.constant"() {value = dense<[6]> : tensor<1xi64>} : () -> tensor<1xi64>
    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %mean_scaled = "stablehlo.divide"(%mean_broadcast, %mean_divisor) : (tensor<6x7xf32>, tensor<1xi64>) -> tensor<6x7xf32>

    // Compute variance
    // diff = input - mean
    %diff = "stablehlo.subtract"(%gemm_bias_added, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // square diff
    %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // sum squared diff over batch
    %sum_diff_squared = "stablehlo.reduce"(%diff_squared, %dim0, "stablehlo.add") : (tensor<6x7xf32>, tensor<1xi64>) -> tensor<7xf32>
    // variance = sum / (batch_size)
    %variance = "stablehlo.divide"(%sum_diff_squared, %mean_divisor) : (tensor<7xf32>, tensor<1xi64>) -> tensor<7xf32>
    // broadcast variance
    %variance_broadcast = "stablehlo.broadcast_in_dim"(%variance) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7xf32>

    // Normalize: (x - mean) / sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<[1e-5]> : tensor<1xf32>} : () -> tensor<1xf32>
    %variance_eps = "stablehlo.add"(%variance_broadcast, %epsilon) : (tensor<6x7xf32>, tensor<1xf32>) -> tensor<6x7xf32>
    %inv_sqrt = "stablehlo.rsqrt"(%variance_eps) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %normalized = "stablehlo.multiply"(%diff, %inv_sqrt) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Scale and shift: gamma (weight), beta (bias)
    %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %scaled = "stablehlo.multiply"(%normalized, %bn_weight_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %shifted = "stablehlo.add"(%scaled, %bn_bias_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: GELU activation
    // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
    %inv_sqrt2 = "stablehlo.constant"() {value = dense<[0.70710678]> : tensor<1xf32>} : () -> tensor<1xf32>
    %x_div_sqrt2 = "stablehlo.divide"(%shifted, %inv_sqrt2) : (tensor<6x7xf32>, tensor<1xf32>) -> tensor<6x7xf32>
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %one = "stablehlo.constant"() {value = dense<[1.0]> : tensor<1xf32>} : () -> tensor<1xf32>
    %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<1xf32>) -> tensor<6x7xf32>
    %erf_plus_one = "stablehlo.add"(%erf_x, %one_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %half = "stablehlo.constant"() {value = dense<[0.5]> : tensor<1xf32>} : () -> tensor<1xf32>
    %gelu = "stablehlo.multiply"(%half, "stablehlo.multiply"(%shifted, %erf_plus_one)) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 4: ReLU activation
    %zero = "stablehlo.constant"() {value = dense<[0.0]> : tensor<1xf32>} : () -> tensor<1xf32>
    %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {
      broadcast_dimensions = dense<[0]> : tensor<1xi64>
    } : (tensor<1xf32>) -> tensor<6x7xf32>
    %relu = "stablehlo.maximum"(%gelu, %zero_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the final tensor
    return %relu : tensor<6x7xf32>
  }
}

