// StableHLO program implementing the described model's forward pass
module {
  func.func @main(%arg0: tensor<7x7xf32>,        // gemm.weight
                   %arg1: tensor<7xf32>,          // gemm.bias
                   %arg2: tensor<7xf32>,          // batch_norm.weight
                   %arg3: tensor<7xf32>,          // batch_norm.bias
                   %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
    // Step 1: GEMM (Linear layer)
    // %arg0: weight (7x7), %arg1: bias (7), input: %arg4 (6x7)
    // We need to perform: x @ weight^T + bias
    // Transpose weight to get (7x7) -> (7x7) (no change), but for clarity, do transpose
    %weight_t = "stablehlo.transpose"(%arg0) {permutation = dense<[1, 0]>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
    // Perform dot_general: (6x7) x (7x7) -> (6x7)
    %gemm = "stablehlo.dot_general"(%arg4, %weight_t) {
      dimension_numbers = dense<{
        input_batch_dimensions = [0],
        input_contracting_dimensions = [1],
        output_batch_dimensions = [0],
        output_contracting_dimensions = [1]
      }>
    } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias: broadcast bias to (6x7)
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
      broadcast_dimensions = dense<[0]>
    } : (tensor<7xf32>) -> tensor<6x7xf32>
    %gemm_bias = "stablehlo.add"(%gemm, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 2: BatchNorm1d
    // batch_norm parameters: weight and bias (both shape 7)
    // Input shape: (6,7)
    // Compute mean and variance over batch dimension (dim=0)
    %mean = "stablehlo.reduce"(%gemm_bias, %c0) {
      dimensions = dense<[0]>,
      reduction_kind = "add"
    } : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    // Divide sum by batch size (6)
    %batch_size = "stablehlo.constant"() {value = dense<6> : tensor<0xi32>} : () -> tensor<0xi32>
    %mean_f32 = "stablehlo.convert"(%mean) : (tensor<7xf32>) -> tensor<7xf32>
    %batch_size_f32 = "stablehlo.convert"(%batch_size) : (tensor<0xi32>) -> tensor<7xf32>
    %mean_div = "stablehlo.div"(%mean_f32, %batch_size_f32) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
    // Compute variance: sum of squared differences
    %diff = "stablehlo.subtract"(%gemm_bias, "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = dense<[0]>}) : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %var_sum = "stablehlo.reduce"(%diff_sq, %c0) {
      dimensions = dense<[0]>,
      reduction_kind = "add"
    } : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    %var_div = "stablehlo.div"(%var_sum, %batch_size_f32) : (tensor<7xf32>, tensor<7xf32>) -> tensor<7xf32>
    // Add epsilon for numerical stability
    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %var_eps = "stablehlo.add"(%var_div, %epsilon) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>
    // Compute stddev
    %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<7xf32>) -> tensor<7xf32>
    // Normalize
    // Broadcast mean and stddev to shape (6,7)
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = dense<[0]>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = dense<[0]>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %x_centered = "stablehlo.subtract"(%gemm_bias, %mean_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %x_norm = "stablehlo.divide"(%x_centered, %stddev_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Scale and shift: batch_norm.weight and batch_norm.bias
    %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = dense<[0]>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[0]>} : (tensor<7xf32>) -> tensor<6x7xf32>
    %x_scaled = "stablehlo.multiply"(%x_norm, %bn_weight_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %x_bn = "stablehlo.add"(%x_scaled, %bn_bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Step 3: GELU activation
    // GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
    %sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623730951 : f32>} : () -> tensor<f32>
    %x_div_sqrt2 = "stablehlo.divide"(%x_bn, %sqrt2) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>
    %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
    %one = "stablehlo.constant"() {value = dense<1.0 : f32>} : () -> tensor<f32>
    %one_plus_erf = "stablehlo.add"(%one, %erf_x) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    %gelu = "stablehlo.multiply"(%x_bn, "stablehlo.multiply"(%one_plus_erf, %c0_5)) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
    // Note: For simplicity, approximate GELU as x * 0.5 * (1 + erf(x / sqrt(2)))

    // Step 4: ReLU activation
    %zero = "stablehlo.constant"() {value = dense<0.0 : f32>} : () -> tensor<f32>
    %relu = "stablehlo.maximum"(%gelu, %zero) : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x7xf32>

    // Return the final tensor
    return %relu : tensor<6x7xf32>
  }
}

// StableHLO program to transpose the last two dimensions of a 3D tensor
