    // Actually, after transpose, shape is [2,3,4], but we need [3,2,4]
    // So, we need to permute again to get [3,2,4]
    %final_transpose = "stablehlo.transpose"(%transposed) {permutation = dense<[1, 0, 2]> : tensor<3xi64>} : (tensor<2x3x4xf32>) -> tensor<3x2x4xf32>
