    //                       kernel_input_feature_dimension=1, kernel_output_feature_dimension=0, kernel_spatial_dimensions={2}}
    //   feature_group_count: 1

    // For transposed convolution, the "convolution" operation with appropriate parameters performs the operation.
    // In StableHLO, transposed convolution is achieved via convolution with specific parameters.
    // Alternatively, use "stablehlo.convolution" with "dimension_numbers" set for transposed convolution.

    // Define dimension numbers for transposed convolution
    %dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2],
      kernel_input_feature_dimension = 1,
      kernel_output_feature_dimension = 0,
      kernel_spatial_dimensions = [2],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2]
    }

    // Set convolution parameters
    %conv_result = "stablehlo.convolution"(%arg1, %weight, 
