module {
  // Function: main
  func.func @main(%arg0: tensor<7x7x3xf32>, %arg1: tensor<6x7x8xf32>) -> tensor<6x7x10xf32> {
    // %arg0: conv1d_transpose.weight, shape: [in_channels=7, out_channels=7, kernel_size=3]
    // %arg1: input tensor, shape: [6,7,8]
