    // Step 2: Prepare weight tensor
    // %weight: [7,7,3]
    // For conv_transpose, weight shape: [in_channels, out_channels, kernel_size]
    // We need to transpose weight to match the expected shape for conv_transpose
    // PyTorch's ConvTranspose1d expects weight shape: [in_channels, out_channels, kernel_size]
    // Assuming %arg0 is already in shape [7,7,3], no transpose needed

    // Step 3: Perform convolution transpose
    // Using "mhlo.convolution" with appropriate parameters
    // Set dimension numbers for 1D transposed convolution
    // Input shape: [batch, in_channels, length]
    // Weight shape: [in_channels, out_channels, kernel_size]
    // Output shape: [batch, out_channels, length_out]

    // Define convolution dimension numbers
    %dimension_numbers = "mhlo.convolution.dimension_numbers"() -> (mhlo.ConvolutionDimensionNumbers) {
      // dimension_numbers:
      // input spatial dims: 2
      // kernel spatial dims: 2
      // output spatial dims: 2
      // batch dimension: 0
      // feature dimension: 1
      // spatial dims: 2
      // For 1D convolution, spatial dims are 2
      // The dimension numbers are:
      // input: {batch=0, feature=1, spatial=2}
      // kernel: {input_feature=0, output_feature=1, spatial=2}
      // output: {batch=0, feature=1, spatial=2}
      mhlo.ConvolutionDimensionNumbers {
        input_batch_dimension = 0 : i64,
        input_feature_dimension = 1 : i64,
        input_spatial_dimensions = [2] : tensor<i64>,
        kernel_input_feature_dimension = 0 : i64,
        kernel_output_feature_dimension = 1 : i64,
        kernel_spatial_dimensions = [2] : tensor<i64>,
        output_batch_dimension = 0 : i64,
        output_feature_dimension = 1 : i64,
        output_spatial_dimensions = [2] : tensor<i64>
      }
    }

    // Set convolution window parameters
    %window = "mhlo.convolution.window"() {
      // For transposed convolution, set padding, stride, output_padding accordingly
      // Here, assuming stride=1, padding=0, output_padding=0
      // For simplicity, set window parameters accordingly
      padding = dense<[0, 0]> : tensor<2xi64>,
      stride = dense<[1, 1]> : tensor<2xi64>,
      dilation = dense<[1, 1]> : tensor<2xi64>,
      window_dimensions = dense<[3, 1]> : tensor<2xi64>,
      window_strides = dense<[1, 1]> : tensor<2xi64>,
      padding_low = dense<[0, 0]> : tensor<2xi64>,
      padding_high = dense<[0, 0]> : tensor<2xi64>,
      window_dilations = dense<[1, 1]> : tensor<2xi64>
    } : mhlo.ConvolutionDimensionNumbers

    // Perform convolution transpose
    %conv_result = "mhlo.convolution"(%input_reshaped, %arg0, %dimension_numbers, %window) : (tensor<6x8x7xf32>, tensor<7x7x3xf32>) -> tensor<6x8x10xf32>

    // Step 4: Transpose back to [6,7,10]
    // Current shape: [6,8,10]
    // Transpose to [6,7,10]
    %output_transposed = "mhlo.transpose"(%conv_result) {permutation = dense<[0,2,1]> : tensor<3xi64>} : tensor<6x10x8xf32>

    // Step 5: Slice to get shape [6,7,10]
    // Since the shape is [6,10,8], need to slice to get size 7 in dimension 1
    // But the shape is [6,10,8], so slice in dimension 1 from 0 to 7
    %slice = "mhlo.slice"(%output_transposed) {
      start_indices = dense<[0,0,0] : tensor<3xi64>>,
      limit_indices = dense<[6,7,10] : tensor<3xi64>>,
      strides = dense<[1,1,1] : tensor<3xi64>>
    } : tensor<6x7x10xf32>

    // Return the sliced tensor
    return %slice : tensor<6x7x10xf32>
  }
}

