// StableHLO program implementing the MaxPool3D operation as specified.
// The input tensor is of shape [16,6,7,7,7], output shape [16,6,2,2,2].

module {
  // Entry function with specified signature.
  func.func @main(%arg0: tensor<16x6x7x7x7xf32>) -> tensor<16x6x2x2x2xf32> {
    // Constants for kernel size, stride, padding, dilation.
    %c0 = constant 0 : index
    %c1 = constant 1 : index
    %c2 = constant 2 : index
    %c3 = constant 3 : index

    // Kernel size = 3
    %kernel_size = constant 3 : index
    // Stride = 2
    %stride = constant 2 : index
    // Padding = 1
    %padding = constant 1 : index
    // Dilation = 3
    %dilation = constant 3 : index

    // Get input shape: [16,6,7,7,7]
    %input_shape = shape %arg0 : tensor<16x6x7x7x7xf32>
    // Extract dimensions
    %dim0 = tensor.dim %input_shape, %c0 : tensor<16x6x7x7x7xf32> -> index
    %dim1 = tensor.dim %input_shape, %c1 : tensor<16x6x7x7x7xf32> -> index
    %dim2 = tensor.dim %input_shape, %c2 : tensor<16x6x7x7x7xf32> -> index
    %dim3 = tensor.dim %input_shape, %c3 : tensor<16x6x7x7x7xf32> -> index
    %dim4 = tensor.dim %input_shape, %c3 : tensor<16x6x7x7x7xf32> -> index

    // Compute output shape for each spatial dimension:
    // output_dim = floor((input_dim + 2*padding - dilation*(kernel_size - 1) - 1)/stride + 1)
    // For each spatial dimension:
    // numerator = input_dim + 2*padding - dilation*(kernel_size - 1) - 1
    // denominator = stride
    // output_dim = floor(numerator / denominator) + 1

    // Compute numerator for each spatial dimension
    %kernel_minus_one = subi %kernel_size, %c1 : index
    %dilation_times_kernel_minus_one = muli %dilation, %kernel_minus_one : index
    %padding_times_two = muli %padding, 2 : index

    // For dim2
    %num_dim2 = subi %dim2, %c1 : index
    %num_dim2 = subi (addi %dim2, %padding_times_two), %c0 : index
    %num_dim2 = subi (addi %dim2, %padding_times_two), %dilation_times_kernel_minus_one : index
    %num_dim2 = subi (addi %dim2, %padding_times_two), %c1 : index

    // Actually, better to do step by step:
    // numerator_dim2 = input_dim2 + 2*padding - dilation*(kernel_size - 1) - 1
    %temp1_dim2 = addi %dim2, %padding_times_two : index
    %temp2_dim2 = subi %temp1_dim2, %dilation_times_kernel_minus_one : index
    %numerator_dim2 = subi %temp2_dim2, %c1 : index

    // For dim3
    %temp1_dim3 = addi %dim3, %padding_times_two : index
    %temp2_dim3 = subi %temp1_dim3, %dilation_times_kernel_minus_one : index
    %numerator_dim3 = subi %temp2_dim3, %c1 : index

    // For dim4
    %temp1_dim4 = addi %dim4, %padding_times_two : index
    %temp2_dim4 = subi %temp1_dim4, %dilation_times_kernel_minus_one : index
    %numerator_dim4 = subi %temp2_dim4, %c1 : index

    // Compute output sizes
    // output_dim = floor(numerator / stride) + 1
    %output_dim2 = addi (floordivf %numerator_dim2, %stride), %c1 : index
    %output_dim3 = addi (floordivf %numerator_dim3, %stride), %c1 : index
    %output_dim4 = addi (floordivf %numerator_dim4, %stride), %c1 : index

    // Now, perform the max pooling operation
    // Use 'reduce_window' with max operation
    // window dimensions: [1, 1, kernel_size, kernel_size, kernel_size]
    // strides: [1, 1, stride, stride, stride]
    // padding: [ [0,0], [0,0], [padding,padding], [padding,padding], [padding,padding] ]

    // Define window dimensions
    %window_dims = tensor.from_elements [1 : index, 1 : index, %kernel_size, %kernel_size, %kernel_size] : tensor<5xindex>
    // Define strides
    %strides = tensor.from_elements [1 : index, 1 : index, %stride, %stride, %stride] : tensor<5xindex>
    // Define padding for each dimension
    // For batch and channels: no padding
    // For spatial dims: padding
    %padding_low = tensor.from_elements [0 : index, 0 : index, %padding, %padding, %padding] : tensor<5xindex>
    %padding_high = tensor.from_elements [0 : index, 0 : index, %padding, %padding, %padding] : tensor<5xindex>
    // Compose padding as a list of pairs
    %padding_list = "stablehlo.padding"(%padding_low, %padding_high) : (tensor<5xindex>, tensor<5xindex>) -> !stablehlo.PaddingConfig

    // Perform reduce_window max pooling
    %maxpooled = "stablehlo.reduce_window"(
      %arg0,
      %c0, // initial value for max
      "max",
      %window_dims,
      %strides,
      %padding_list
    ) : (tensor<16x6x7x7x7xf32>, tensor<xf32>, string, tensor<5xindex>, tensor<5xindex>, !stablehlo.PaddingConfig) -> tensor<16x6x2x2x2xf32>

    // Return the result
    return %maxpooled : tensor<16x6x2x2x2xf32>
  }
}

