    %one = "constant"() {value = dense<1.0>} : () -> tensor<f32>
    %denominator = "add"(%one, %exp_neg) : (tensor<f32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>
    %sigmoid = "divide"(%one, %denominator) : (tensor<f32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>

    // Step 5: GroupNorm
    // GroupNorm parameters: weight and bias shape: (16,)
    // Broadcast weight and bias to match
    %gn_weight_bcast = "broadcast_in_dim"(%arg4) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
    %gn_bias_bcast = "broadcast_in_dim"(%arg5) {broadcast_dimensions = [0]} : (tensor<16xf32>) -> tensor<16x1x1x1xf32>
    // Apply group normalization
    // For simplicity, approximate group norm as: (x - mean) / sqrt(var + epsilon) * weight + bias
    // But since MLIR does not have direct group norm, we can approximate with mean and variance reduction
    // Compute mean over spatial dims (1,2)
    %mean = "reduce"(%sigmoid) {dimensions = [1, 2], kind = "mean"} : (tensor<16x14x14x16xf32>) -> tensor<16x1x1x16xf32>
    // Broadcast mean to match shape
    %mean_bcast = "broadcast_in_dim"(%mean) {broadcast_dimensions = [0, 1, 2, 3]} : (tensor<16x1x1x16xf32>) -> tensor<16x14x14x16xf32>
    // Subtract mean
    %centered = "subtract"(%sigmoid, %mean_bcast) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>
    // Compute variance
    %squared = "multiply"(%centered, %centered) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>
    %var = "reduce"(%squared) {dimensions = [1, 2], kind = "mean"} : (tensor<16x14x14x16xf32>) -> tensor<16x1x1x16xf32>
    // Add epsilon for numerical stability
    %epsilon = "constant"() {value = dense<1e-5>} : () -> tensor<f32>
    %var_eps = "add"(%var, %epsilon) : (tensor<16x1x1x16xf32>, tensor<f32>) -> tensor<16x1x1x16xf32>
    // Compute sqrt of variance + epsilon
    %stddev = "sqrt"(%var_eps) : (tensor<16x1x1x16xf32>) -> tensor<16x1x1x16xf32>
    // Normalize
    %normalized = "divide"(%centered, %stddev) : (tensor<16x14x14x16xf32>, tensor<16x1x1x16xf32>) -> tensor<16x14x14x16xf32>
    // Apply weight
    %weighted = "multiply"(%normalized, %gn_weight_bcast) : (tensor<16x14x14x16xf32>, tensor<16x1x1x16xf32>) -> tensor<16x14x14x16xf32>
    // Add bias
    %gn_bias_bcast_full = "broadcast_in_dim"(%gn_bias_bcast) {broadcast_dimensions = [0, 1, 2, 3]} : (tensor<16x1x1x16xf32>) -> tensor<16x14x14x16xf32>
    %gn_output = "add"(%weighted, %gn_bias_bcast_full) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>

    // Transpose back to NCHW
    %output = "transpose"(%gn_output) {permutation = [0, 3, 1, 2]} : tensor<16x14x14x16xf32> to tensor<16x16x14x14xf32>
    return %output : tensor<16x16x14x14xf32>
  }
}

