// Complete StableHLO program implementing the described model's forward pass
module {
  func.func @main(
    %arg0: tensor<16x1x1xf32>,             // bias
    %arg1: tensor<16x1x1xf32>,             // scale
    %arg2: tensor<16x8x3x3xf32>,           // conv.weight
    %arg3: tensor<16xf32>,                 // conv.bias
    %arg4: tensor<16x1x1xf32>,             // group_norm.weight
    %arg5: tensor<16x1x1xf32>,             // group_norm.bias
    %arg6: tensor<16x8x16x16xf32>          // input
  ) -> tensor<16x16x14x14xf32> {
    // Step 1: Convolution
    %conv = "stablehlo.convolution"(%arg6, %arg2)
      {window_strides = dense<1,1> : tensor<2xi64>,
       padding = dense<0,0,0,0> : tensor<4xi64>,
       lhs_dilation = dense<1,1> : tensor<2xi64>,
       rhs_dilation = dense<1,1> : tensor<2xi64>,
       window_reversal = dense<0,0> : tensor<2xi1>,
       feature_group_count = 1 : i64,
       batch_group_count = 1 : i64,
       precision_config = "DEFAULT"} : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

    // Step 2: Add bias
    // Broadcast bias to match convolution output shape
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg3, dense<0> : tensor<1>, dense<0> : tensor<0>) {broadcast_dimensions = dense<0> : tensor<1>} 
    // Reshape bias to (16,1,1,1) for broadcasting
    %bias_reshaped = "stablehlo.reshape"(%bias_bcast) {shape = tensor<16x1x1x1>} 
    // Broadcast bias to match conv output shape (16x16x14x14)
    %bias_broadcasted = "stablehlo.broadcast_in_dim"(%bias_reshaped, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}

    %add_bias = "stablehlo.add"(%conv, %bias_broadcasted)

    // Step 3: Scale
    // Broadcast scale to match shape
    %scale_bcast = "stablehlo.broadcast_in_dim"(%arg1, dense<0> : tensor<1>, dense<0> : tensor<0>) {broadcast_dimensions = dense<0> : tensor<1>}
    %scale_reshaped = "stablehlo.reshape"(%scale_bcast) {shape = tensor<16x1x1x1>}
    %scale_broadcasted = "stablehlo.broadcast_in_dim"(%scale_reshaped, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}

    %scaled = "stablehlo.multiply"(%add_bias, %scale_broadcasted)

    // Step 4: Sigmoid
    %neg_one = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>}
    %neg_scaled = "stablehlo.negate"(%scaled)
    %exp_neg = "stablehlo.exp"(%neg_scaled)
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>}
    %denominator = "stablehlo.add"(%one, %exp_neg)
    %sigmoid = "stablehlo.divide"(%one, %denominator)

    // Step 5: Group Normalization
    // Compute mean and variance over spatial dims (2,3)
    // Reduce mean
    %axes = "stablehlo.constant"() {value = dense<[2,3]> : tensor<2xi64>}
    %mean = "stablehlo.reduce"(%sigmoid, %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}, "stablehlo.reduce_op" {reduction = "add"})
      {dimensions = %axes, keep_dims = true}
    // Compute variance
    %diff = "stablehlo.subtract"(%sigmoid, "stablehlo.broadcast_in_dim"(%mean, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>})
    %diff_sq = "stablehlo.multiply"(%diff, %diff)
    %var_sum = "stablehlo.reduce"(%diff_sq, %zero, "stablehlo.reduce_op" {reduction = "add"})
      {dimensions = %axes, keep_dims = true}
    // Compute variance = sum / count
    %count = 16 * 14 * 14 : i64
    %var = "stablehlo.divide"(%var_sum, "stablehlo.constant"() {value = dense<196.0 : f32>})
    // Compute stddev = sqrt(variance + epsilon)
    %epsilon = "stablehlo.constant"() {value = dense<1e-5 : f32>}
    %var_eps = "stablehlo.add"(%var, %epsilon)
    %stddev = "stablehlo.sqrt"(%var_eps)

    // Normalize
    %normalized = "stablehlo.subtract"(
      "stablehlo.broadcast_in_dim"(%sigmoid, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>},
      "stablehlo.broadcast_in_dim"(%mean, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}
    )
    %normalized_scaled = "stablehlo.divide"(
      "stablehlo.broadcast_in_dim"(%normalized, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>},
      "stablehlo.broadcast_in_dim"(%stddev, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}
    )

    // Step 6: Apply scale and bias for group norm
    // Broadcast group_norm.weight and bias
    %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg4, dense<0> : tensor<1>, dense<0> : tensor<0>) {broadcast_dimensions = dense<0>}
    %gn_weight_reshaped = "stablehlo.reshape"(%gn_weight_bcast) {shape = tensor<16x1x1x1>}
    %gn_weight_broadcasted = "stablehlo.broadcast_in_dim"(%gn_weight_reshaped, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}

    %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg5, dense<0> : tensor<1>, dense<0> : tensor<0>) {broadcast_dimensions = dense<0>}
    %gn_bias_reshaped = "stablehlo.reshape"(%gn_bias_bcast) {shape = tensor<16x1x1x1>}
    %gn_bias_broadcasted = "stablehlo.broadcast_in_dim"(%gn_bias_reshaped, dense<4> : tensor<1>, dense<4> : tensor<1>) {broadcast_dimensions = dense<0,1,2,3>}

    // Final normalized output: scale and bias
    %norm_scaled = "stablehlo.multiply"(%normalized_scaled, %gn_weight_broadcasted)
    %norm_biased = "stablehlo.add"(%norm_scaled, %gn_bias_broadcasted)

    // Output: reshape to (16,16,14,14)
    // Already in shape, so just return
    "stablehlo.return"(%norm_biased)
  }
}

