func.func @main(
    %arg0: tensor<16x1x1xf32>,   // bias
    %arg1: tensor<16x1x1xf32>,   // scale
    %arg2: tensor<16x8x3x3xf32>, // conv.weight
    %arg3: tensor<16xf32>,       // conv.bias
    %arg4: tensor<16x1x1xf32>,   // group_norm.weight
    %arg5: tensor<16x1x1xf32>,   // group_norm.bias
    %arg6: tensor<16x8x16x16xf32> // input
  ) -> tensor<16x16x14x14xf32> {
    // Aliases for parameters
    %bias = %arg0 : tensor<16x1x1xf32>
    %scale = %arg1 : tensor<16x1x1xf32>
    %conv_weight = %arg2 : tensor<16x8x3x3xf32>
    %conv_bias = %arg3 : tensor<16xf32>
    %gn_weight = %arg4 : tensor<16x1x1xf32>
    %gn_bias = %arg5 : tensor<16x1x1xf32>
    %input = %arg6 : tensor<16x8x16x16xf32>

    // Step 1: Convolution
    %conv = "stablehlo.convolution"(%input, %conv_weight) {
      window_strides = dense<1,1> : tensor<2xi64>,
      padding = dense<0,0,0,0> : tensor<4xi64>,
      lhs_dilation = dense<1,1> : tensor<2xi64>,
      rhs_dilation = dense<1,1> : tensor<2xi64>,
      window_reversal = dense<false> : tensor<1xi1>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : tensor<16x16x14x14xf32>

    // Step 2: Add bias
    // Broadcast bias to match conv output shape
    %bias_bcast = "stablehlo.broadcast_in_dim"(%bias, dense<16,14,14> : tensor<3xi64>) {
      broadcast_dimensions = [1, 2]
    } : tensor<16x14x14xf32>
    %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias, dense<16,14,14> : tensor<3xi64>) {
      broadcast_dimensions = [0, 1, 2]
    } : tensor<16x14x14xf32>
    %conv_bias_bcast_full = "stablehlo.broadcast_in_dim"(%conv_bias, dense<16,14,14> : tensor<3xi64>) {
      broadcast_dimensions = [0, 1, 2]
    } : tensor<16x14x14xf32>
    // Actually, for bias addition, broadcast bias over spatial dims
    // So, broadcast bias of shape [16,1,1] to [16,14,14]
    %bias_bcast_full = "stablehlo.broadcast_in_dim"(%bias, dense<16,14,14> : tensor<3xi64>) {
      broadcast_dimensions = [0, 1, 2]
    } : tensor<16x14x14xf32>
    %add_bias = "stablehlo.add"(%conv, %bias_bcast_full) : (tensor<16x16x14x14xf32>, tensor<16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 3: Scale (element-wise multiply)
    // Broadcast scale to match shape
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale, dense<16,14,14> : tensor<3xi64>) {
      broadcast_dimensions = [0, 1, 2]
    } : tensor<16x14x14xf32>
    %scaled = "stablehlo.multiply"(%add_bias, %scale_bcast) : (tensor<16x16x14x14xf32>, tensor<16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 4: Apply sigmoid
    // sigmoid(x) = 1 / (1 + exp(-x))
    %neg = "stablehlo.negate"(%scaled) : tensor<16x16x14x14xf32>
    %exp_neg = "stablehlo.exp"(%neg) : tensor<16x16x14x14xf32>
    %one = "stablehlo.constant"() { value = dense<1.0> : tensor<f32> } : tensor<f32>
    %denominator = "stablehlo.add"(%one, %exp_neg) : (tensor<f32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>
    %sigmoid = "stablehlo.divide"(%one, %denominator) : (tensor<f32>, tensor<16x16x14x14xf32>) -> tensor<16x16x14x14xf32>

    // Step 5: Group Normalization
    // For group norm, compute mean and variance over groups
    // group_norm has 8 groups, each with 2 channels (since out_channels=16)
    // Reshape to [16, 14, 14, 8, 2] for group norm
    // But StableHLO group norm expects input shape [N, C, H, W], with parameters
    // For simplicity, use "stablehlo.group_norm" operation
    // Note: As of current StableHLO, group_norm may not be directly available, so implement manually

    // Reshape to [N, C, H, W]
    // Already in shape [16, 16, 14, 14]
    // Compute mean over groups
    // Reshape to [16, 8, 2, 14, 14]
    %reshaped_for_gn = "stablehlo.reshape"(%sigmoid) { shape = dense<16,8,2,14,14> } : tensor<16x8x2x14x14xf32>
    // Compute mean over axes [2,3,4] (channels within group, height, width)
    %mean_axes = dense<2,3,4> : tensor<3xi64>
    %mean = "stablehlo.reduce"(%reshaped_for_gn, %zero = "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) {
      dimensions = %mean_axes,
      reduction = "add"
    } : tensor<16x8x2x14x14xf32>
    // Divide by number of elements in reduction axes (2*14*14=392)
    %num_elements = "stablehlo.constant"() { value = dense<392.0> : tensor<f32> }
    %mean_div = "stablehlo.divide"(%mean, %num_elements) : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8x2x14x14xf32>

    // Compute variance
    // Subtract mean from each element
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div, dense<16,8,2,14,14> : tensor<5xi64>) {
      broadcast_dimensions = [0,1,2,3,4]
    } : tensor<16x8x2x14x14xf32>
    %diff = "stablehlo.subtract"(%reshaped_for_gn, %mean_bcast) : (tensor<16x8x2x14x14xf32>, tensor<16x8x2x14x14xf32>) -> tensor<16x8x2x14x14xf32>
    // Square differences
    %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<16x8x2x14x14xf32>, tensor<16x8x2x14x14xf32>) -> tensor<16x8x2x14x14xf32>
    // Sum over axes [2,3,4]
    %sum_diff_sq = "stablehlo.reduce"(%diff_sq, %zero = "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) {
      dimensions = %mean_axes,
      reduction = "add"
    } : tensor<16x8x2x14x14xf32>
    // Variance = sum / number of elements
    %var = "stablehlo.divide"(%sum_diff_sq, %num_elements) : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8x2x14x14xf32>
    // Broadcast variance
    %var_bcast = "stablehlo.broadcast_in_dim"(%var, dense<16,8,2,14,14> : tensor<5xi64>) {
      broadcast_dimensions = [0,1,2,3,4]
    }

// Complete StableHLO program implementing the described model's forward pass
module {
  // Function signature:
  // %main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32>
  func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
    // Aliases for inputs
    %linear_weight = %arg0 : tensor<7x7xf32>        // weight parameter
    %linear_bias = %arg1 : tensor<7xf32>            // bias parameter
    %x_input = %arg2 : tensor<6x7xf32>              // input tensor

    // Step 1: GEMM (matrix multiplication)
    // Compute: x = matmul(%x_input, transpose(%linear_weight))
    %weight_T = "mhlo.transpose"(%linear_weight) {permutation = dense<[1, 0]>} : tensor<7x7xf32>
    %x_gemm = "mhlo.dot_general"(%x_input, %weight_T)
      {dimension_numbers = {lhs_contracting_dimensions = dense<[1]>>,
                            rhs_contracting_dimensions = dense<[0]>>,
       lhs_batch_dimensions = dense<[]>,
       rhs_batch_dimensions = dense<[]>}} : tensor<6x7xf32>

    // Add bias: broadcast bias to match shape
    // %linear_bias: tensor<7xf32>
    // Broadcast bias to shape <6x7>
    %bias_bcast = "mhlo.broadcast_in_dim"(%linear_bias)
      {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    %x_bias = "mhlo.add"(%x_gemm, %bias_bcast) : tensor<6x7xf32>

    // Step 2: LogSumExp over dim=1 (rows)
    // Reduce sum of exp, then take log
    %exp_x = "mhlo.exp"(%x_bias) : tensor<6x7xf32>
    %sum_exp = "mhlo.reduce"(%exp_x) {dimensions = dense<[1]>, to_apply = @reduce_sum} : tensor<6xf32>
    // To get logsumexp, compute log of sum_exp
    %log_sum_exp = "mhlo.log"(%sum_exp) : tensor<6xf32>
    // Expand dims to keep dim=1 (keepdim=True)
    %log_sum_exp_bcast = "mhlo.broadcast_in_dim"(%log_sum_exp)
      {broadcast_dimensions = dense<[1]>, shape = tensor<6x1xf32>} : tensor<6xf32> -> tensor<6x1xf32>
    // Now, shape is [6,1]

    // Step 3: LeakyReLU with negative_slope=0.01
    // LeakyReLU(x) = max(x, x * alpha)
    %alpha = constant 0.01 : f32
    %x_mul_alpha = "mhlo.mul"(%log_sum_exp_bcast, %alpha) : tensor<6x1xf32>
    %x_leaky_relu = "mhlo.maximum"(%log_sum_exp_bcast, %x_mul_alpha) : tensor<6x1xf32>

    // Step 4: Second LeakyReLU (same as above)
    %x_leaky_relu2 = "mhlo.maximum"(%x_leaky_relu, "mhlo.mul"(%x_leaky_relu, %alpha) : tensor<6x1xf32>)

    // Step 5: GELU activation
    // Approximate GELU using erf: GELU(x) ≈ 0.5 * x * (1 + erf(x / sqrt(2)))
    // Compute x / sqrt(2)
    %sqrt2 = constant 1.41421356237 : f32
    %x_div_sqrt2 = "mhlo.div"(%x_leaky_relu2, %sqrt2) : tensor<6x1xf32>
    // erf(x / sqrt(2))
    %erf_x = "chlo.erf"(%x_div_sqrt2) : tensor<6x1xf32>
    // 1 + erf(...)
    %one = constant 1.0 : f32
    %one_bcast = "mhlo.broadcast_in_dim"(%one) {broadcast_dimensions = dense<[0]>, shape = tensor<6x1xf32>}
    %erf_plus_one = "mhlo.add"(%one_bcast, %erf_x) : tensor<6x1xf32>
    // 0.5 * x * (1 + erf)
    %half = constant 0.5 : f32
    %x_times_half = "mhlo.mul"(%x_leaky_relu2, %half) : tensor<6x1xf32>
    %gelu = "mhlo.mul"(%x_times_half, %erf_plus_one) : tensor<6x1xf32>

    // Step 6: Second GELU (same as above)
    // Repeat GELU approximation
    %x_div_sqrt2_2 = "mhlo.div"(%gelu, %sqrt2) : tensor<6x1xf32>
    %erf_x2 = "chlo.erf"(%x_div_sqrt2_2) : tensor<6x1xf32>
    %erf_plus_one_2 = "mhlo.add"(%one_bcast, %erf_x2) : tensor<6x1xf32>
    %x_times_half_2 = "mhlo.mul"(%gelu, %half) : tensor<6x1xf32>
    %gelu2 = "mhlo.mul"(%x_times_half_2, %erf_plus_one_2) : tensor<6x1xf32>

    // Final output: shape [6,1]
    return %gelu2 : tensor<6x1xf32>
  }

  // Helper reduction function for sum
  func.func private @reduce_sum(%operand: tensor<*>) -> tensor<*> {
    "mhlo.reduce"(%operand) {dimensions = dense<[1]>, to_apply = @reduce_sum_body} : tensor<*>
  }

  func.func private @reduce_sum_body(%accum: tensor<*>, %x: tensor<*>) -> tensor<*> {
    "mhlo.add"(%accum, %x)
  }
