module {
  func.func @main(%arg0: tensor<16x16x3xf32>, %arg1: tensor<16x16x16xf32>) -> tensor<16x16x3xf32> {
    // %arg0: conv1d.weight, shape: [out_channels, in_channels, kernel_size] = [16, 16, 3]
    // %arg1: input tensor, shape: [batch_size, in_channels, length] = [16, 16, 16]
    // Output: shape: [batch_size, out_channels, length_out]

    // Define constants for convolution parameters
    %batch_size = constant 16 : index
    %in_channels = constant 16 : index
    %out_channels = constant 16 : index
    %kernel_size = constant 3 : index
    %stride = constant 3 : index
    %dilation = constant 4 : index
    %length_in = constant 16 : index

    // Compute output length: length_out = floor((length_in - (dilation * (kernel_size - 1) + 1)) / stride) + 1
    // For input length=16, kernel=3, dilation=4, stride=3:
    // effective_kernel = dilation * (kernel_size - 1) + 1 = 4 * 2 + 1 = 9
    // length_out = floor((16 - 9) / 3) + 1 = floor(7/3) + 1 = 2 + 1 = 3
    %effective_kernel = "dilated_kernel"() { 
      %temp1 = muli %dilation, %kernel_size : i32
      %temp2 = addi %temp1, 1 : i32
      return %temp2 : i32
    }
    %length_in_minus_effective = subi %length_in, %effective_kernel : i32
    %length_out_float = divf %length_in_minus_effective, %stride : f32
    %length_out_int = floor %length_out_float : i32
    %length_out = addi %length_out_int, 1 : i32

    // Reshape %arg0 (weight) to 1D convolution filter: shape [out_channels, in_channels, kernel_size]
    // Already in shape: [16, 16, 3]
    // For conv_general_dilated, the filter shape is [out_channels, in_channels, kernel_size]
    // No reshape needed.

    // Prepare input tensor for convolution: shape [batch_size, in_channels, length_in]
    // Already in shape: [16, 16, 16]

    // Set convolution parameters
    %window_dimensions = "constant"() { value = 3 : index } // kernel size
    %strides = "constant"() { value = 3 : index }
    %dilations = "constant"() { value = 4 : index }
    %padding = "padding"() { padding_low = 0 : i32, padding_high = 0 : i32, padding_left = 0 : i32, padding_right = 0 : i32 }

    // Perform convolution
    %conv_result = "stablehlo.convolution" 
     (%arg1, %arg0) 
      { window_dimensions = %window_dimensions, 
        window_strides = %strides, 
        lhs_dilation = "1"(), 
        rhs_dilation = %dilations, 
        padding = %padding, 
        feature_group_count = 1 : i32 } : (tensor<16x16x16xf32>, tensor<16x16x3xf32>) -> tensor<16x16x3xf32>

    // The output shape is [batch_size, out_channels, length_out]
    // which is [16, 16, 3]
    return %conv_result : tensor<16x16x3xf32>
  }
}

