module {
  func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
    // Step 1: Transposed convolution
    %conv = "convolution.transposed"(%arg2, %arg0) {window_dimensions = dense<3x3xf32>, strides = dense<2x2xi64>, padding = dense<1x1xi64>, output_padding = dense<1x1xi64>} : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

    // Step 2: Mish activation: mish(x) = x * tanh(softplus(x))
    // Compute softplus(x) = log(1 + exp(x))
    %one = "constant"() {value = dense<1.0xf32>} : () -> tensor<f32>
    %exp_x = "elementwise.exp"(%conv) : (tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>
    %add_one = "elementwise.add"(%exp_x, %one) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>
    %softplus = "math.log"(%add_one) : (tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>
    // Compute tanh(softplus)
    %tanh_sp = "math.tanh"(%softplus) : (tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>
    // Mish(x) = x * tanh(softplus(x))
    %mish = "elementwise.multiply"(%conv, %tanh_sp) : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

    // Step 3: Add bias (%arg1), which is shape [7], need to broadcast to match shape
    // Reshape bias to [1, 7, 1, 1] for broadcasting
    %bias_shape = "constant"() {value = dense<1x7x1x1xi64>} : () -> tensor<4xi64>
    %bias_broadcast_shape = "reshape"(%arg1, %bias_shape) : (tensor<7xf32>, tensor<4xi64>) -> tensor<1x7x1x1xf32>
    // Broadcast bias to match shape of mish output
    %bias_broadcast = "broadcast_in_dim"(%bias_broadcast_shape) {broadcast_dimensions = dense<1,2,3,4>} : (tensor<1x7x1x1xf32>) -> tensor<6x7x12x12xf32>
    %add_bias = "elementwise.add"(%mish, %bias_broadcast) : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

    // Step 4: Hardtanh activation with min=-1, max=1
    %min_val = "constant"() {value = dense<-1.0f32>} : () -> tensor<f32>
    %max_val = "constant"() {value = dense<1.0f32>} : () -> tensor<f32>
    %clamped_min = "compare.lt"(%add_bias, %min_val) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<i1>
    %clamped_max = "compare.gt"(%add_bias, %max_val) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<i1>
    // Use select to clamp
    %clamped_lower = "select"(%clamped_min, %min_val, %add_bias) : (tensor<i1>, tensor<f32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>
    %clamped = "select"(%clamped_max, %max_val, %clamped_lower) : (tensor<i1>, tensor<f32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

    // Step 5: Scale the output by 2
    %scale_const = "constant"() {value = dense<2.0f32>} : () -> tensor<f32>
    %scaled_output = "elementwise.multiply"(%clamped, %scale_const) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>

    return %scaled_output : tensor<6x7x12x12xf32>
  }
}

