    // V shape: [batch, heads, seq_len, embed_dim]
    // attention_weights shape: [batch, heads, seq_len, seq_len]
    // We need to perform batched matmul: attention_weights @ V
    // But attention_weights shape: [batch, heads, seq_len, seq_len]
    // V shape: [batch, heads, seq_len, embed_dim]
    // Output shape: [batch, heads, seq_len, embed_dim]

