    // Convert size to float for division
    %size_float = "stablehlo.convert"(%size_const) : (tensor<i32>) -> tensor<f32>

    // Step 5: Compute batch mean: sum / size
    %batch_mean = "stablehlo.div"(%sum, %size_float) : (tensor<f32>, tensor<f32>) -> tensor<f32>

    // Return the result
    return %batch_mean : tensor<f32>
  }
