    // axes for reduction: [2,3]
    %axes_reduce = constant dense<[2,3]> : tensor<2xi64>
    %mean = "mhlo.reduce"(%arg2, %c0, "add", %axes_reduce) : (tensor<14x16x16x16xf32>, f32, string, tensor<2xi64>) -> tensor<14x16x16x16xf32>
    // Divide sum by number of elements (16*16=256)
    %num_elements = constant dense<256> : tensor<f32>
    %mean_div = "mhlo.divide"(%mean, %num_elements) : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>

    // Step 2: Broadcast mean to shape [14,16,16,16]
    // The mean shape is [14,16,16,16], same as input, so broadcasting is trivial
    // But to be safe, use broadcast_in_dim
    %mean_bcast = "mhlo.broadcast_in_dim"(%mean_div, tensor<4>{14,16,16,16}, dense<[0,1,2,3]>) : (tensor<14x16x16x16xf32>, tensor<4>, tensor<4>) -> tensor<14x16x16x16xf32>

    // Step 3: Compute variance
    // diff = input - mean
    %diff = "mhlo.subtract"(%arg2, %mean_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // square diff
    %diff_sq = "mhlo.multiply"(%diff, %diff) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // sum of squared diff
    %sum_sq = "mhlo.reduce"(%diff_sq, %c0, "add", %axes_reduce) : (tensor<14x16x16x16xf32>, f32, string, tensor<2xi64>) -> tensor<14x16x16x16xf32>
