    %var = "mhlo.divide"(%sum_sq, %num_elements) : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>

    // Step 4: Compute stddev = sqrt(variance + epsilon)
    // epsilon: small constant, e.g., 1e-5
    %epsilon = constant dense<1e-5> : tensor<f32>
    %var_eps = "mhlo.add"(%var, %epsilon) : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>
    %stddev = "mhlo.sqrt"(%var_eps) : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Step 5: Normalize
    // normalized = (input - mean) / stddev
    %diff_norm = "mhlo.subtract"(%arg2, %mean_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %normalized = "mhlo.divide"(%diff_norm, %stddev) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Step 6: Apply scale (weight) and bias
    // %arg0: weight, shape [16]
