    %scale_bcast = "mhlo.broadcast_in_dim"(%arg0, tensor<4>{14,16,16,16}, dense<[0,1,2,3]>) : (tensor<16xf32>, tensor<4>, tensor<4>) -> tensor<14x16x16x16xf32>
