    // scale * normalized
    %scaled = "mhlo.multiply"(%normalized, %scale_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // add bias
    %out = "mhlo.add"(%scaled, %bias_bcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

