    %var_plus_epsilon = "elementwise.add"(%var, %epsilon) : (tensor<14x16x16x16xf32>, tensor<f32>) -> tensor<14x16x16x16xf32>
    %stddev = "elementwise.sqrt"(%var_plus_epsilon) : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Step 4: Normalize
    %broadcast_mean_for_norm = "broadcast_in_dim"(%mean_input) {broadcast_dimensions = dense<[0,1]>} : (tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %normalized = "elementwise.sub"(%arg2, %broadcast_mean_for_norm) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %normalized_by_std = "elementwise.div"(%normalized, %stddev) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Step 5: Apply scale (weight) and bias
    // %arg0: weight, shape [16]
    // %arg1: bias, shape [16]
    %scale_broadcast = "broadcast_in_dim"(%arg0) {broadcast_dimensions = dense<[1,2,3]>} : (tensor<16>) -> tensor<14x16x16x16xf32>
    %bias_broadcast = "broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1,2,3]>} : (tensor<16>) -> tensor<14x16x16x16xf32>
    %scaled = "elementwise.mul"(%normalized_by_std, %scale_broadcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    %biased = "elementwise.add"(%scaled, %bias_broadcast) : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>

    // Output
    return %biased : tensor<14x16x16x16xf32>
  }
}

