// StableHLO program implementing the described model's forward pass with group normalization
module {
  func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32> {
    // %arg0: weight (scale) for GroupNorm, shape [16]
    // %arg1: bias for GroupNorm, shape [16]
    // %arg2: input tensor, shape [14,16,16,16]

    // Constants
    %c8 = constant 8 : index
    %c1 = constant 1 : index
    %c0 = constant 0 : index
    %c16 = constant 16 : index
    %c14 = constant 14 : index

    // Get input shape
    %shape_input = shape %arg2 : tensor<14x16x16x16xf32>
    // Extract batch size (14)
    %batch_size = tensor.dim %shape_input, %c0 : tensor<14x16x16x16xf32>
    // Extract channels (16)
    %channels = tensor.dim %shape_input, %c1 : tensor<14x16x16x16xf32>
    // Spatial dims
    %dim1 = tensor.dim %shape_input, %c2 : tensor<14x16x16x16xf32>
    %dim2 = tensor.dim %shape_input, %c3 : tensor<14x16x16x16xf32>

    // Compute number of groups
    // num_groups = 8 (constant)
    // num_channels = 16 (from arg0 shape)
    // group_size = channels / num_groups = 2
    // For simplicity, define as constant
    %num_groups = constant 8 : index
    %group_size = constant 2 : index

    // Reshape input to [batch, num_groups, group_size, height, width]
    // shape: [14,8,2,16,16]
    // First, reshape input
    %reshaped_input_shape = tensor<5xindex> : tensor<5 x index>
    %reshaped_input_shape = tensor.build %batch_size, %num_groups, %group_size, %dim1, %dim2 : tensor<5xindex>
    %input_reshaped = "stablehlo.reshape"(%arg2, %reshaped_input_shape) : (tensor<14x16x16x16xf32>, tensor<5xindex>) -> tensor<14x8x2x16x16>

    // Compute mean over [2,3,4] (group, height, width) axes for normalization
    // axes: [2,3,4]
    %axes = "stablehlo.constant"() {value = dense_int_attr<array<i64, 3>>({2,3,4})} : () -> tensor<3xi64>
    %mean = "stablehlo.reduce"(%input_reshaped, %c0, "stablehlo.add", "stablehlo.reduce.operand") {
      reduction_dims = %axes
    } : (tensor<14x8x2x16x16>, index) -> tensor<14x8x1x1x1>
    // Divide sum by number of elements (2*16*16=512)
    %num_elements = 512.0 : f32
    %mean_div = "stablehlo.divf"(%mean, %num_elements) : (tensor<14x8x1x1x1>, f32) -> tensor<14x8x1x1x1>

    // Broadcast mean to shape of input for subtraction
    // shape: [14,8,2,16,16]
    %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div, %reshaped_input_shape, %c0, %c1, %c2, %c3, %c4) : (tensor<14x8x1x1x1>, tensor<5xindex>, (i64, i64, i64, i64, i64)) -> tensor<14x8x2x16x16>

    // Subtract mean
    %centered = "stablehlo.sub"(%input_reshaped, %mean_bcast) : (tensor<14x8x2x16x16>, tensor<14x8x2x16x16>) -> tensor<14x8x2x16x16>

    // Compute variance: mean of squared deviations
    %squared = "stablehlo.mul"(%centered, %centered) : (tensor<14x8x2x16x16>, tensor<14x8x2x16x16>) -> tensor<14x8x2x16x16>
    %var_sum = "stablehlo.reduce"(%squared, %c0, "stablehlo.add", "stablehlo.reduce.operand") {
      reduction_dims = %axes
    } : (tensor<14x8x2x16x16>, index) -> tensor<14x8x1x1x1>
    // Variance = sum / num_elements
    %var = "stablehlo.divf"(%var_sum, %num_elements) : (tensor<14x8x1x1x1>, f32) -> tensor<14x8x1x1x1>

    // Compute stddev = sqrt(variance + epsilon)
    %epsilon = 1e-5 : f32
    %var_plus_eps = "stablehlo.addf"(%var, %epsilon) : (tensor<14x8x1x1x1>, f32) -> tensor<14x8x1x1x1>
    %stddev = "stablehlo.sqrt"(%var_plus_eps) : (tensor<14x8x1x1x1>) -> tensor<14x8x1x1x1>

    // Broadcast stddev for normalization
    %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev, %reshaped_input_shape, %c0, %c1, %c2, %c3, %c4) : (tensor<14x8x1x1x1>, tensor<5xindex>) -> tensor<14x8x2x16x16>

    // Normalize: (x - mean) / stddev
    %normalized = "stablehlo.divf"(
                    "stablehlo.sub"(%centered, %c0), // subtract mean
                    %stddev_bcast
                  ) : (tensor<14x8x2x16x16>, tensor<14x8x2x16x16>) -> tensor<14x8x2x16x16>

    // Reshape normalized back to original shape [14,16,16,16]
    %normalized_shape = tensor<4xindex> {value = dense_int_attr<array<i64, 4>>({14,16,16,16})}
    %normalized_reshaped = "stablehlo.reshape"(%normalized, %normalized_shape) : (tensor<14x8x2x16x16>, tensor<4xindex>) -> tensor<14x16x16x16>

    // Apply scale (weight) and bias
    // %arg0: scale, shape [16]
    // %arg1: bias, shape [16]
    // Broadcast scale and bias to match input shape
    %scale_bcast = "stablehlo.broadcast_in_dim"(%arg0, tensor<4xindex> {value = dense_int_attr<array<i64, 4>>({14,16,16,16})}, 1, 2, 3) : (tensor<16>, tensor<4xindex>, (i64, i64, i64, i64)) -> tensor<14x16x16x16>
    %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1, tensor<4xindex> {value = dense_int_attr<array<i64, 4>>({14,16,16,16})}, 1, 2, 3) : (tensor<16>, tensor<4xindex>, (i64, i64, i64, i64)) -> tensor<14x16x16x16>

    // Multiply normalized by scale
    %scaled = "stablehlo.mul"(%normalized_reshaped, %scale_bcast) : (tensor<14x16x16x16>, tensor<14x16x16x16>) -> tensor<14x16x16x16>
    // Add bias
    %output = "stablehlo.add"(%scaled, %bias_bcast) : (tensor<14x16x16x16>, tensor<14x16x16x16>) -> tensor<14x16x16x16>

    // Return output
    return %output : tensor<14x16x16x16xf32>
  }
}

