        "stablehlo.return"(%sum) : (tensor<14x16x16x16xf32>) -> ()
      }
    } : (tensor<14x16x16x16xf32>, tensor<14x16x16x16xf32>) -> tensor<14x16x16x16xf32>
    // Compute mean by dividing sum by number of spatial elements (16*16=256)
    %num_spatial = "stablehlo.constant"() {value = dense<256 : i64>} : () -> tensor<i64>
    %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_over_dims) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
