    return %out : tensor<7x3xf32>
  }
}

// StableHLO program to normalize each row of a 7x3 tensor to unit L2 norm
module {
  func.func @main(%x: tensor<7x3xf32>) -> tensor<7x3xf32> {
    // Step 1: Compute x^2
    %x_squared = "stablehlo.multiply" %x, %x : tensor<7x3xf32>

    // Step 2: Reduce sum over the last dimension (k) to get sum_k x[i,k]^2
    %init = "stablehlo.constant"() {value = dense<0.0 : tensor<f32> } : () -> tensor<f32>
    %sum_sq = "stablehlo.reduce"(%x_squared, %init) ({
      ^bb0(%a: tensor<f32>, %b: tensor<f32>): %s = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 1>} : (tensor<7x3xf32>, tensor<f32>) -> tensor<7x1xf32>

    // Step 3: Broadcast sum_k x[i,k]^2 to shape 7x3 for division
    %sum_sq_broadcast = "stablehlo.broadcast_in_dim" %sum_sq {broadcast_dimensions = array<i64: 1>} : tensor<7x1xf32> -> tensor<7x3xf32>

    // Step 4: Compute sqrt of sum_k x[i,k]^2
    %norm = "stablehlo.sqrt" %sum_sq_broadcast : tensor<7x3xf32>

    // Step 5: Divide x by the norm to normalize each row
    %out = "stablehlo.divide" %x, %norm : tensor<7x3xf32>

    return %out : tensor<7x3xf32>
  }
}

// StableHLO program implementing the described model in MLIR dialect
module {
  // Function signature as specified
  func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
    // Aliases for parameters
    %gemm_weight = %arg0 : tensor<16x16xf32>
    %gemm_bias = %arg1 : tensor<16xf32>
    %group_norm_weight = %arg2 : tensor<16xf32>
    %group_norm_bias = %arg3 : tensor<16xf32>
    %input = %arg4 : tensor<16x16xf32>

    // Step 1: GEMM (Linear layer)
    // Perform matrix multiplication: input @ weight^T + bias
    // Note: in MLIR, dot_general with appropriate dimension numbers
    %lhs = %input : tensor<16x16xf32>
    %rhs = %gemm_weight : tensor<16x16xf32>
    // Transpose weight for proper matmul
    %rhs_T = "mhlo.transpose"(%rhs) {permutation = dense<[1, 0]>} : tensor<16x16xf32>
    // Dot general
    %dimension_numbers = {
      input_batching_dimensions = dense<[]>,
      input_contracting_dimensions = dense<[]>,
      output_batching_dimensions = dense<[]>,
      output_contracting_dimensions = dense<[]>
    }
    %gemm_result = "mhlo.dot_general"(%lhs, %rhs_T) {
      dimension_numbers = {
        lhs_batching_dimensions = dense<[]>,
        lhs_contracting_dimensions = dense<1>,
        rhs_batching_dimensions = dense<[]>,
        rhs_contracting_dimensions = dense<0>
      }
    } : tensor<16x16xf32>
    // Add bias
    %gemm_broadcast_bias = "mhlo.broadcast_in_dim"(%gemm_bias) {
      broadcast_dimensions = dense<1>
    } : tensor<16x16xf32>
    %gemm_output = "mhlo.add"(%gemm_result, %gemm_broadcast_bias) : tensor<16x16xf32>

    // Step 2: GroupNorm
    // Compute mean and variance over features (dim=1)
    // Compute mean
    %reduction_dims = dense<1> : tensor<1>
    %mean = "mhlo.reduce"(%gemm_output, 0.0 : f32) {
      dimensions = %reduction_dims,
      reduction_computation = "mhlo.add"
    } : tensor<16xf32>
    // Divide by feature size (16)
    %feature_size = constant 16 : index
    %mean_broadcast = "mhlo.broadcast_in_dim"(%mean) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    %mean_scaled = "mhlo.divide"(%mean_broadcast, %feature_size : index) : tensor<16xf32>

    // Compute variance
    // Subtract mean
    %mean_broadcast2 = "mhlo.broadcast_in_dim"(%mean_scaled) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    %diff = "mhlo.subtract"(%gemm_output, %mean_broadcast2) : tensor<16x16xf32>
    // Square diff
    %diff_squared = "mhlo.multiply"(%diff, %diff) : tensor<16x16xf32>
    // Reduce sum of squared differences
    %sum_diff_squared = "mhlo.reduce"(%diff_squared, 0.0 : f32) {
      dimensions = %reduction_dims,
      reduction_computation = "mhlo.add"
    } : tensor<16xf32>
    // Variance = sum / feature_size
    %variance = "mhlo.divide"(%sum_diff_squared, %feature_size : index) : tensor<16xf32>
    // Broadcast variance
    %variance_broadcast = "mhlo.broadcast_in_dim"(%variance) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    // Add epsilon for numerical stability
    %epsilon = constant 1e-5 : f32
    %variance_eps = "mhlo.add"(%variance_broadcast, %epsilon) : tensor<16xf32>

    // Compute stddev = sqrt(variance + epsilon)
    %stddev = "mhlo.sqrt"(%variance_eps) : tensor<16xf32>
    // Compute reciprocal of stddev
    %recip_stddev = "mhlo.rsqrt"(%variance_eps) : tensor<16xf32>

    // Normalize: (x - mean) / stddev
    %diff_broadcast = "mhlo.broadcast_in_dim"(%mean_scaled) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    %x_centered = "mhlo.subtract"(%gemm_output, %diff_broadcast) : tensor<16x16xf32>
    %x_norm = "mhlo.multiply"(%x_centered, %recip_stddev) : tensor<16x16xf32>

    // Apply scale (group_norm.weight) and bias (group_norm.bias)
    %scale_broadcast = "mhlo.broadcast_in_dim"(%group_norm_weight) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    %bias_broadcast = "mhlo.broadcast_in_dim"(%group_norm_bias) {
      broadcast_dimensions = dense<0>
    } : tensor<16xf32>
    %scaled = "mhlo.multiply"(%x_norm, %scale_broadcast) : tensor<16x16xf32>
    %shifted = "mhlo.add"(%scaled, %bias_broadcast) : tensor<16x16xf32>

    // Step 3: HardTanh activation
    // min_val = -2.0, max_val = 2.0
    %min_val = constant -2.0 : f32
    %max_val = constant 2.0 : f32
    // Apply maximum with min_val
    %clamped_min = "mhlo.maximum"(%shifted, %min_val) : tensor<16x16xf32>
    // Apply minimum with max_val
    %clamped = "mhlo.minimum"(%clamped_min, %max_val) : tensor<16x16xf32>

    // Return the result
    return %clamped : tensor<16x16xf32>
  }
}

