  %twenty_percent = "stablehlo.constant"() {value = dense<0.2> : tensor<f32>} : () -> tensor<f32>

  // Compare x > 0
  %cond = "stablehlo.compare"(%x, %zero) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<2x6xf32>, tensor<2x6xf32>) -> tensor<2x6xi1>

  // Compute 0.2 * x
  %scaled_x = "stablehlo.multiply"(%twenty_percent, %x) : (tensor<f32>, tensor<2x6xf32>) -> tensor<2x6xf32>

  // Select x where condition is true, else 0.2 * x
  %result = "stablehlo.select"(%cond, %x, %scaled_x) : (tensor<2x6xi1>, tensor<2x6xf32>, tensor<2x6xf32>) -> tensor<2x6xf32>

  return %result : tensor<2x6xf32>
}

