    %mask = compare "greater" %x, %zero : tensor<2x6xf32> -> tensor<2x6xi1>

    // Compute scaled_x = 0.2 * x
    %scaled_x = "mul" %twenty_percent, %x : tensor<2x6xf32>

    // Use select to choose between x and scaled_x based on mask
    %out = select %mask, %x, %scaled_x : tensor<2x6xf32>

