  }
}

func.func @main(%arg0: tensor<6x6x3x3x3xf32>, %arg1: tensor<4x6x6x7x8xf32>) -> tensor<4x6x11x13x15xf32> {
    // Aliases for input tensors
    %input_weight = %arg0 : tensor<6x6x3x3x3xf32>
    %input_input = %arg1 : tensor<4x6x6x7x8xf32>

    // Constants for convolution parameters
    %in_channels = constant 6 : i32
    %out_channels = constant 6 : i32
    %kernel_size = constant 3 : i32
    %stride = constant 2 : i32
    %padding = constant 1 : i32
    %groups = constant 4 : i32

