    %depth_in = tensor.extract_dim %input_shape, 2 : tensor<4x6x6x7x8xf32>
    %height_in = tensor.extract_dim %input_shape, 3 : tensor<4x6x6x7x8xf32>
    %width_in = tensor.extract_dim %input_shape, 4 : tensor<4x6x6x7x8xf32>

