    %height_out = arith.subi (arith.muli %height_in, 1), 0 : i32
    %height_out_mul = arith.muli %height_out, %stride : i32
    %height_out_pad = arith.subi %height_out_mul, (arith.muli %padding, 2) : i32
    %height_out_final = arith.addi %height_out_pad, %kernel_size : i32

