    %width_out = arith.subi (arith.muli %width_in, 1), 0 : i32
    %width_out_mul = arith.muli %width_out, %stride : i32
    %width_out_pad = arith.subi %width_out_mul, (arith.muli %padding, 2) : i32
    %width_out_final = arith.addi %width_out_pad, %kernel_size : i32

    // Construct output shape tensor
    %output_shape = tensor %batch_size, %out_channels, %depth_out_final, %height_out_final, %width_out_final : tensor<5xi32>

    // Prepare the input tensor for convolution: shape [batch, in_channels, depth, height, width]
    // The input tensor is already in shape [4,6,6,7,8], matching [batch, channels, D, H, W]
    // No reshaping needed

    // Define the convolution operation
    // Since StableHLO does not have a built-in ConvTranspose3d, we implement it via reverse convolution
    // The approach:
    // 1. Reverse the kernel along spatial dimensions
    // 2. Pad the input appropriately
    // 3. Perform a convolution with the reversed kernel, stride=1, padding=0
    // 4. The output of this convolution is the transposed convolution result

    // Step 1: Reverse the kernel along spatial dimensions (dimensions 2,3,4)
    %reversed_kernel = "stablehlo.reverse"(%input_weight) {dimensions = [2,3,4]} : (tensor<6x6x3x3x3xf32>) -> tensor<6x6x3x3x3xf32>

