    // Compute tanh of inner
    %tanh_inner = "mhlo.tanh"(%inner) : (tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute 1 + tanh_inner
    %one_plus_tanh = "mhlo.add"(%c_one, %tanh_inner) : (f32, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute 0.5 * x * (1 + tanh(...))
    %half_x = "mhlo.multiply"(%c_half, %arg0) : (f32, tensor<6x6xf32>) -> tensor<6x6xf32>
    %gelu = "mhlo.multiply"(%half_x, %one_plus_tanh) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    return %gelu : tensor<6x6xf32>
  }
}

