    %c_sqrt2_over_pi = "stablehlo.constant"() {value = dense<0.7978845608> : tensor<f32>} : () -> tensor<f32> // sqrt(2/pi)

    // Compute x^3
    %x_pow3 = "stablehlo.power"(%arg0, %c_three) : (tensor<6x6xf32>, tensor<1x1xf32>) -> tensor<6x6xf32>
    // But since power expects two tensors, create a tensor of ones for exponent
    // Actually, for power with scalar exponent, use broadcast
    // So, create scalar 3
    %scalar_three = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
    // Broadcast scalar 3 to shape
    %x_pow3 = "stablehlo.power"(%arg0, %scalar_three) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

    // Compute 0.044715 * x^3
    %mul_044715_x3 = "stablehlo.multiply"(%c_044715, %x_pow3) : (tensor<f32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute x + 0.044715 * x^3
    %x_plus_term = "stablehlo.add"(%arg0, %mul_044715_x3) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute sqrt(2/pi)
    // Already have constant %c_sqrt2_over_pi
    // Compute tanh argument: sqrt(2/pi) * (x + 0.044715 * x^3)
    %tanh_arg = "stablehlo.multiply"(%c_sqrt2_over_pi, %x_plus_term) : (tensor<f32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute tanh
    %tanh_res = "stablehlo.tanh"(%tanh_arg) : (tensor<6x6xf32>) -> tensor<6x6xf32>

    // Compute 1 + tanh
    %one_tensor = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %tanh_plus_one = "stablehlo.add"(%tanh_res, %one_tensor) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

    // Compute 0.5 * x
    %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %x_times_half = "stablehlo.multiply"(%arg0, %half) : (tensor<6x6xf32>, tensor<f32>) -> tensor<6x6xf32>

    // Final output: 0.5 * x * (1 + tanh(...))
    %intermediate = "stablehlo.multiply"(%x_times_half, %tanh_plus_one) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Return the result
    return %intermediate : tensor<6x6xf32>
  }
}

// StableHLO program implementing the described model forward pass
module {
  func.func @main(%arg0: tensor<7xf32>,        // scale
                   %arg1: tensor<7x7xf32>,     // gemm.weight
                   %arg2: tensor<7xf32>,       // gemm.bias
                   %arg3: tensor<7xf32>,       // bn.weight
                   %arg4: tensor<7xf32>,       // bn.bias
                   %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> { // input
    // Step 1: Compute gemm: x = input @ weight^T + bias
    // input: [6,7], weight: [7,7]
    %input = %arg5 : tensor<6x7xf32>
    %weight = %arg1 : tensor<7x7xf32>
    %bias = %arg2 : tensor<7xf32>
    // Transpose weight for dot_general
    %weight_t = "mhlo.transpose"(%weight) {permutation = dense<[1,0]> : tensor<2xi64>} : tensor<7x7xf32>
    // Dot general: [6,7] x [7,7] -> [6,7]
    %dot = "mhlo.dot_general"(%input, %weight_t)
            {dimension_numbers = dense<{
                input_batch_dims = [],
                input_contracting_dims = [1],
                output_batch_dims = [],
                output_contracting_dims = [1]
            }>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
    // Add bias
    // bias broadcast to [6,7]
    %bias_bcast = "mhlo.broadcast_in_dim"(%bias) {broadcast_dimensions = dense<[1]>} : tensor<7xf32> -> tensor<6x7xf32>
    %gemm_out = "mhlo.add"(%dot, %bias_bcast) : tensor<6x7xf32>

    // Step 2: Scale: element-wise multiply by scale
    // scale shape: [7], need to broadcast to [6,7]
    %scale_bcast = "mhlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    %scaled = "mhlo.mul"(%gemm_out, %scale_bcast) : tensor<6x7xf32>

    // Step 3: Batch normalization
    // batch norm: x = (x - mean) / sqrt(var + eps) * weight + bias
    // Since in training mode, mean and var are batch statistics
    // Compute mean over batch dimension (dim 0)
    %zero = "mhlo.constant"() : () -> tensor<0xf32>
    %one = "mhlo.constant"() : () -> tensor<0xf32>
    // Compute mean: reduce over dim 0
    %mean = "mhlo.reduce"(%scaled, %zero) {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    // Compute squared difference
    %mean_bcast = "mhlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    %diff = "mhlo.sub"(%scaled, %mean_bcast) : tensor<6x7xf32>
    %diff_sq = "mhlo.mul"(%diff, %diff) : tensor<6x7xf32>
    // Compute variance: mean of squared differences over batch
    %var = "mhlo.reduce"(%diff_sq, %zero) {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<0xf32>) -> tensor<7xf32>
    // Add epsilon
    %eps = "mhlo.constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %var_eps = "mhlo.add"(%var, %eps) : tensor<7xf32>
    // Compute rsqrt of variance + eps
    %rsqrt_var = "mhlo.rsqrt"(%var_eps) : tensor<7xf32>
    // Broadcast rsqrt to [6,7]
    %rsqrt_bcast = "mhlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    // Normalize: (x - mean) * rsqrt
    %x_centered = "mhlo.sub"(%scaled, %mean_bcast) : tensor<6x7xf32>
    %x_norm = "mhlo.mul"(%x_centered, %rsqrt_bcast) : tensor<6x7xf32>
    // Scale by bn.weight
    %bn_weight_bcast = "mhlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    %x_scaled = "mhlo.mul"(%x_norm, %bn_weight_bcast) : tensor<6x7xf32>
    // Add bn.bias
    %bn_bias_bcast = "mhlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = dense<[0]>} : tensor<7xf32> -> tensor<6x7xf32>
    %output = "mhlo.add"(%x_scaled, %bn_bias_bcast) : tensor<6x7xf32>

    // Return the output tensor
    return %output : tensor<6x7xf32>
  }
}

