    %x_bn = "stablehlo.add"(%x_scaled_bn, %bn_bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

    // Return the normalized, scaled, shifted tensor
    return %x_bn : tensor<6x7xf32>
  }
