    // But StableHLO reduce with 'mean' is not directly available, so do sum then divide
    %sum = "stablehlo.reduce"(%conv_op, %dims, "stablehlo.reduce-add") {reduction_kind = "add"} : (tensor<6x6x6x6xf32>, tensor<2xi64>) -> tensor<6x6x6x6xf32>
    // Compute number of elements in reduction dims: 6*6=36
    %reduction_size = "stablehlo.constant"() {value = dense<36.0f> : tensor<f32>} : () -> tensor<f32>
