    // squared difference
    %diff_sq = "stablehlo.mul"(%diff, %diff) : (tensor<6x6x6x6xf32>, tensor<6x6x6x6xf32>) -> tensor<6x6x6x6xf32>
    // sum of squared differences
    %sum_sq = "stablehlo.reduce"(%diff_sq, %dims, "stablehlo.reduce-add") {reduction_kind = "add"} : (tensor<6x6x6x6xf32>, tensor<2xi64>) -> tensor<6x6x6x6xf32>
