    // So start at 0, size 4 in dims 2 and 3, keep full in batch and channels
    // For slicing, specify start and limit
    // For batch and channels, take full
    // So, start indices: batch=0, channel=0, height=0, width=0
    // sizes: batch=6, channel=7, height=4, width=4
    %start_indices_full = "stablehlo.constant"() {value = dense<0,0,0,0> : tensor<4xi64>} : () -> tensor<4xi64>
