    %add_bias = "add"(%gemm_result, %bias_broadcast) : tensor<16x16xf32>

    // Step 3: Hardtanh activation
    // Hardtanh with default min=-1.0, max=1.0
    %minus_one = "constant"() {value = dense<[-1.0]> : tensor<f32>} : () -> tensor<1xf32>
