    // Step 4: Mish activation
    // Mish(x) = x * tanh(softplus(x))
    // softplus(x) = log(1 + exp(x))
    %exp_x = "exponential"(%clamped) : tensor<16x16xf32>
    %one_const = "constant"() {value = dense<1.0 : f32>} : () -> tensor<1xf32>
    %softplus = "add"(%exp_x, %one_const) : tensor<16x16xf32>
    %log_softplus = "log"(%softplus) : tensor<16x16xf32>
    %tanh_sp = "tanh"(%log_softplus) : tensor<16x16xf32>
    %mish = "multiply"(%clamped, %tanh_sp) : tensor<16x16xf32>

    // Step 5: GroupNorm
    // GroupNorm with num_groups=16, num_channels=16
    // For simplicity, assume mean and variance are computed over batch dimension
    // Compute mean over batch (dimension 0)
    %dim0 = "constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>
