    %mean_broadcast = "broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0]>} : tensor<16xf32> -> tensor<16x16xf32>
    %diff = "subtract"(%mish, %mean_broadcast) : tensor<16x16xf32>
    %diff_sq = "multiply"(%diff, %diff) : tensor<16x16xf32>
    %var_sum = "reduce"(%diff_sq, %dim0) {reduction_kind = "add"} : tensor<16x16xf32> -> tensor<16xf32>
    %batch_size_f = "constant"() {value = dense<16.0 : f32>} : () -> tensor<f32>
    %variance = "divide"(%var_sum, %batch_size_f) : tensor<16xf32>
    // Compute stddev
    %epsilon = "constant"() {value = dense<1e-5 : f32>} : () -> tensor<f32>
    %variance_plus_epsilon = "add"(%variance, %epsilon) : tensor<16xf32>
    %stddev = "math.sqrt"(%variance_plus_epsilon) : tensor<16xf32>
    // Broadcast stddev and mean for normalization
    %stddev_broadcast = "broadcast_in_dim"(%stddev) {broadcast_dimensions = dense<[0]>} : tensor<16xf32> -> tensor<16x16xf32>
    %mean_broadcast2 = "broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0]>} : tensor<16xf32> -> tensor<16x16xf32>
    // Normalize
    %normalized = "subtract"(%mish, %mean_broadcast2) : tensor<16x16xf32>
    %norm = "divide"(%normalized, %stddev_broadcast) : tensor<16x16xf32>
    // Apply groupnorm scale and bias
    %groupnorm_weight_broadcast = "broadcast_in_dim"(%arg3) {broadcast_dimensions = dense<[0]>} : tensor<16xf32> -> tensor<16x16xf32>
    %groupnorm_bias_broadcast = "broadcast_in_dim"(%arg4) {broadcast_dimensions = dense<[0]>} : tensor<16xf32> -> tensor<16x16xf32>
    %scaled = "multiply"(%norm, %groupnorm_weight_broadcast) : tensor<16x16xf32>
    %shifted = "add"(%scaled, %groupnorm_bias_broadcast) : tensor<16x16xf32>

    // Return the final tensor
    return %shifted : tensor<16x16xf32>
  }
}

