    // Clip at 6 (max)
    %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
    %hardtanh = "stablehlo.minimum"(%clipped_min, %six) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>

