    // softplus(x) = log(1 + exp(x))
    %exp_x = "stablehlo.exponential"(%hardtanh) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    %one_const = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    %softplus = "stablehlo.log"("stablehlo.add"(%exp_x, %one_const) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // tanh(softplus(x))
    %tanh_sp = "stablehlo.tanh"(%softplus) : (tensor<16x16xf32>) -> tensor<16x16xf32>
    // Mish(x) = x * tanh(softplus(x))
    %mish = "stablehlo.multiply"(%hardtanh, %tanh_sp) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

