    %rows = "stablehlo.iota"() {iota_dimension = 0 : i64, iota_shape = tensor<6x6xf32>} : () -> tensor<6x6xf32>
    // Generate column indices (iota along the second dimension)
    %cols = "stablehlo.iota"() {iota_dimension = 1 : i64, iota_shape = tensor<6x6xf32>} : () -> tensor<6x6xf32>
    // Create a constant tensor of 1.0 for comparison
    %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
    // Create a constant tensor of 0.0 for selection
    %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    // Compare row indices <= column indices
    %cmp = "stablehlo.compare"(%rows, %cols) {comparison_direction = "LE"} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>
